            <p class="text-gray-600 mt-2">Manage your menu, track logistics, and print display cards.</p>
        </header>

        <div class="grid grid-cols-1 md:grid-cols-3 gap-8">
            <!-- Form Column -->
            <div class="md:col-span-1 bg-white p-6 rounded-xl shadow-sm h-fit border border-gray-100">
