            // Update counter
            counter.innerText = `${dishes.length} dish${dishes.length === 1 ? '' : 'es'}`;

            if (dishes.length === 0) {
                checklistContainer.innerHTML = `<p class="text-gray-400 text-center py-4">No dishes added yet. Fill out the form to start.</p>`;
