                            <p class="text-gray-500"><strong class="text-gray-700">Servings:</strong> ${dish.servings} | <strong class="text-gray-700">Setup:</strong> ${dish.tempNotes}</p>
                        </div>
                    </div>
                    <button onclick="deleteDish(${dish.id})" class="text-red-500 hover:text-red-700 text-sm font-medium ml-2 px-2 py-1">
                        Remove
                    </button>
                </div>
            `).join('');

            // Render Print Cards (Standard tent card size ratio)
            printCardsContainer.innerHTML = dishes.map(dish => `
                <div class="border-2 border-dashed border-gray-400 p-6 rounded-lg bg-white card-break flex flex-col justify-between h-48 shadow-sm">
                    <div>
                        <h2 class="text-2xl font-bold text-gray-900 border-b-2 border-indigo-100 pb-1 mb-2">${dish.name}</h2>
                        <p class="text-sm text-gray-700"><strong class="text-indigo-900">Ingredients/Allergens:</strong> ${dish.allergens}</p>
                    </div>
                    <div class="flex justify-between items-end border-t border-gray-200 pt-2 text-xs text-gray-500">
                        <span>Est. Servings: ${dish.servings}</span>
                        <span class="italic">${dish.tempNotes !== 'None' ? dish.tempNotes : ''}</span>
                    </div>
                </div>
            `).join('');
        }

        function copyChecklist() {
            if (dishes.length === 0) return;
            const text = dishes.map(d => 
                `[${d.arrived ? 'X' : ' '}] ${d.name}\n   Allergens: ${d.allergens}\n   Servings: ${d.servings}\n   Notes: ${d.tempNotes}`
            ).join('\n\n');

            navigator.clipboard.writeText(text);
            alert('Checklist copied to clipboard!');
        }

        function downloadJSON() {
            if (dishes.length === 0) return;
            const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(dishes, null, 2));
            const downloadAnchor = document.createElement('a');
            downloadAnchor.setAttribute("href", dataStr);
            downloadAnchor.setAttribute("download", "potluck_checklist.json");
            document.body.appendChild(downloadAnchor);
            downloadAnchor.click();
            downloadAnchor.remove();
        }
    </script>
</body>
</html>

